package com.lolfm.simulator;import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;
class BaseThreatTest{
 @Test void threatProgressesFromNoneToNexusAndIsSideIndependent(){GameState s=LateGameTestSupport.state();BaseThreatEvaluator e=new BaseThreatEvaluator();assertEquals(BaseThreatLevel.NONE,e.evaluate(s,TeamSide.RED).overallLevel());LateGameTestSupport.destroyThroughInhibitorTower(s,TeamSide.RED,Lane.MID);assertEquals(BaseThreatLevel.INHIBITOR_THREAT,e.evaluate(s,TeamSide.RED).overallLevel());assertEquals(BaseThreatLevel.NONE,e.evaluate(s,TeamSide.BLUE).overallLevel());s.getMapState().getLaneState(TeamSide.RED,Lane.MID).destroyInhibitor(900);assertEquals(BaseThreatLevel.NEXUS_TURRET_THREAT,e.evaluate(s,TeamSide.RED).overallLevel());s.getMapState().getBaseState(TeamSide.RED).destroyOneNexusTurret();s.getMapState().getBaseState(TeamSide.RED).destroyOneNexusTurret();assertEquals(BaseThreatLevel.NEXUS_THREAT,e.evaluate(s,TeamSide.RED).overallLevel());s.getMapState().getBaseState(TeamSide.RED).destroyNexus(1000);assertEquals(BaseThreatLevel.MATCH_ENDED,e.evaluate(s,TeamSide.RED).overallLevel());}
 @Test void snapshotDerivationDoesNotMutateMap(){GameState s=LateGameTestSupport.state();BaseThreatEvaluator e=new BaseThreatEvaluator();var before=e.evaluate(s,TeamSide.BLUE);e.evaluate(s,TeamSide.BLUE);assertEquals(before,e.evaluate(s,TeamSide.BLUE));assertEquals(2,s.getMapState().getBaseState(TeamSide.BLUE).getNexusTurretsRemaining());}
}
